/*
 * A210208  Triangle read by rows in which row n lists the divisors of n that
 *          are prime powers, A000961.
 * https://oeis.org/A210208
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is the nth element of the triangle whose row m lists the
 *            divisors of m that are prime powers (including 1), in increasing
 *            order. The sequence is generated by a sieve of smallest prime
 *            factors and a cumulative counter of the number of prime‑power
 *            divisors per row. The implementation is O(n lo...
 * Range:     u8 n <= 927, u16 n <= 9964, u32 n <= 9964, u64 n <= 9964,
 *            u128 n <= 9964, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

/* External integer types */
extern seq_t a(idx_t);

/* -----  Static state for spf (smallest prime factor) and cum ---- */
static idx_t *spf          = NULL;   /* spf[i] = smallest prime factor of i   */
static idx_t  spf_limit    = 0;      /* largest i for which spf is computed   */

static idx_t *cum          = NULL;   /* cum[i] = total terms up to row i      */
static idx_t  cum_limit    = 0;      /* largest i for which cum is filled    */
static idx_t  cum_capacity = 0;      /* current allocated capacity for cum    */

/* ------------------------------------------------------------------- */
/* Ensure that spf[i] is defined for all 1 <= i <= limit.             */
/* ------------------------------------------------------------------- */
static void
ensure_spf(idx_t limit)
{
    if (limit <= spf_limit)
        return;

    /* Allocate new array and fill initial values */
    size_t new_cap = (size_t)limit + 1;
    idx_t *new_spf = (idx_t *)calloc(new_cap, sizeof(idx_t));
    if (!new_spf)
        exit(1);

    for (idx_t i = 0; i <= limit; ++i)
        new_spf[i] = i;
    new_spf[0] = 0;
    new_spf[1] = 1;

    /* Sieve of Eratosthenes to fill small prime factors */
    for (idx_t i = 2; i <= limit / i; ++i) {
        if (new_spf[i] == i) {            /* i is prime */
            for (idx_t j = i * i; j <= limit; j += i)
                if (new_spf[j] == j)
                    new_spf[j] = i;
        }
    }

    if (spf)
        free(spf);
    spf       = new_spf;
    spf_limit = limit;
}

/* ------------------------------------------------------------------- */
/* Ensure that cum[i] is defined for all 0 <= i <= limit.  The array  */
/* cum[i] holds the cumulative count of prime‑power divisors up to row */
/* i.  cum[0] is defined as 0.                                          */
/* ------------------------------------------------------------------- */
static void
ensure_cum(idx_t limit)
{
    if (limit <= cum_limit)
        return;

    /* First make sure we have enough capacity for cum */
    if (cum == NULL) {
        cum_capacity = (size_t)limit + 1;
        cum = (idx_t *)calloc(cum_capacity, sizeof(idx_t));
        if (!cum)
            exit(1);
        cum[0] = 0;
    } else if (cum_capacity < (size_t)limit + 1) {
        size_t new_cap = cum_capacity ? cum_capacity << 1 : limit + 1;
        while (new_cap < (size_t)limit + 1)
            new_cap <<= 1;
        idx_t *tmp = (idx_t *)realloc(cum, new_cap * sizeof(idx_t));
        if (!tmp)
            exit(1);
        cum = tmp;
        cum_capacity = new_cap;
    }

    /* Compute new cumulative values.  We need spf up to 'limit' as well. */
    ensure_spf(limit);

    for (idx_t i = cum_limit + 1; i <= limit; ++i) {
        idx_t temp = i;
        idx_t sum_exp = 0;
        while (temp > 1) {
            idx_t p = spf[temp];
            idx_t e = 0;
            while (temp % p == 0) {
                temp /= p;
                ++e;
            }
            sum_exp += e;
        }
        idx_t tau_pp = sum_exp + 1;   /* 1 plus all prime powers of i */
        cum[i] = cum[i - 1] + tau_pp;
    }
    cum_limit = limit;
}

/* ------------------------------------------------------------------- */
/* Locate the row that contains the nth term by binary search.        */
/* ------------------------------------------------------------------- */
static idx_t
find_row(idx_t n)
{
    /* Grow the cumulative table until it contains n. */
    while (cum_limit < 1 || cum[cum_limit] < n) {
        /* Double the limit (or start at 1) to keep growth amortised. */
        idx_t new_limit = cum_limit ? cum_limit << 1 : 1;
        if (new_limit < n)
            new_limit = n;
        ensure_cum(new_limit);
    }

    /* Binary search in cum[1..cum_limit] for smallest r with cum[r] >= n */
    idx_t low = 1, high = cum_limit;
    while (low < high) {
        idx_t mid = low + (high - low) / 2;
        if (cum[mid] >= n)
            high = mid;
        else
            low = mid + 1;
    }
    return low;
}

/* ------------------------------------------------------------------- */
/* Main sequence function.                                              */
/* ------------------------------------------------------------------- */
seq_t
a(idx_t n)
{
    if (n == 0)   /* undefined for n = 0, return 0 as a graceful value */
        return (seq_t)0;

    /* Find the row containing the n-th term */
    idx_t row = find_row(n);

    /* Position of the term within that row (1‑based) */
    idx_t prev_count = (row > 0 ? cum[row - 1] : (idx_t)0);
    idx_t pos_in_row = n - prev_count;  /* 1 ≤ pos_in_row ≤ tau_pp(row) */

    if (pos_in_row == 1)   /* first term of every row is 1 */
        return (seq_t)1;

    /* Generate all prime‑power divisors of 'row' except 1 */
    /* We use a small, fixed‑size array – the number of prime powers
       in any row up to 2×10⁶ is comfortably less than 64.           */
    seq_t ppowers[64];
    int   count = 0;

    idx_t tmp = row;
    while (tmp > 1) {
        idx_t p = spf[tmp];
        idx_t exp = 0;
        while (tmp % p == 0) {
            tmp /= p;
            ++exp;
        }
        seq_t val = 1;
        for (idx_t k = 1; k <= exp; ++k) {
            val = val * (seq_t)p;
            ppowers[count++] = val;
        }
    }

    /* Sort the prime powers in ascending order */
    for (int i = 0; i < count - 1; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (ppowers[j] < ppowers[i]) {
                seq_t t = ppowers[i];
                ppowers[i] = ppowers[j];
                ppowers[j] = t;
            }
        }
    }

    /* pos_in_row > 1, so the desired divisor is ppowers[pos_in_row-2] */
    return ppowers[(int)(pos_in_row) - 2];
}
